/**
 * CSP Nonce Plugin for Rspack
 *
 * Injects nonce placeholder into script and style tags generated by HtmlRspackPlugin.
 * nginx's sub_filter replaces the placeholder (__CSP_NONCE__) with a unique
 * per-request value from $request_id.
 *
 * This enables strict CSP policies by replacing 'unsafe-inline' with nonce-based
 * script/style allowlisting.
 *
 * Usage:
 *   new CspNoncePlugin({ placeholder: '__CSP_NONCE__' })
 *
 * How it works:
 * 1. Hooks into HtmlRspackPlugin's alterAssetTags event
 * 2. Adds nonce="__CSP_NONCE__" to all script and style tags
 * 3. nginx sub_filter replaces __CSP_NONCE__ with $request_id in HTML responses
 * 4. Browser validates nonce matches CSP header's 'nonce-{value}'
 */

const PLUGIN_NAME = 'CspNoncePlugin';

class CspNoncePlugin {
  constructor(options = {}) {
    this.placeholder = options.placeholder || '__CSP_NONCE__';
  }

  apply(compiler) {
    compiler.hooks.compilation.tap(PLUGIN_NAME, (compilation) => {
      // Get HtmlRspackPlugin hooks
      const HtmlPlugin = compiler.webpack?.HtmlRspackPlugin || require('@rspack/core').HtmlRspackPlugin;

      if (!HtmlPlugin || !HtmlPlugin.getCompilationHooks) {
        console.warn(`[${PLUGIN_NAME}] HtmlRspackPlugin not found, skipping nonce injection`);
        return;
      }

      const hooks = HtmlPlugin.getCompilationHooks(compilation);

      // Hook into alterAssetTags to add nonce to script and style tags
      hooks.alterAssetTags.tap(PLUGIN_NAME, (data) => {
        // Add nonce to script tags
        if (data.assetTags && data.assetTags.scripts) {
          data.assetTags.scripts.forEach((tag) => {
            if (tag.tagName === 'script') {
              tag.attributes = tag.attributes || {};
              tag.attributes.nonce = this.placeholder;
            }
          });
        }

        // Add nonce to style tags (for inline styles injected by style-loader)
        if (data.assetTags && data.assetTags.styles) {
          data.assetTags.styles.forEach((tag) => {
            if (tag.tagName === 'style' || tag.tagName === 'link') {
              tag.attributes = tag.attributes || {};
              // Only add nonce to style tags, not link tags (external CSS)
              if (tag.tagName === 'style') {
                tag.attributes.nonce = this.placeholder;
              }
            }
          });
        }

        return data;
      });

      // Also hook into alterAssetTagGroups for additional coverage
      hooks.alterAssetTagGroups.tap(PLUGIN_NAME, (data) => {
        const addNonce = (tags) => {
          tags.forEach((tag) => {
            if (tag.tagName === 'script') {
              tag.attributes = tag.attributes || {};
              tag.attributes.nonce = this.placeholder;
            }
            if (tag.tagName === 'style') {
              tag.attributes = tag.attributes || {};
              tag.attributes.nonce = this.placeholder;
            }
          });
        };

        if (data.headTags) addNonce(data.headTags);
        if (data.bodyTags) addNonce(data.bodyTags);

        return data;
      });
    });
  }
}

module.exports = CspNoncePlugin;
